	u32 max_keys = 0;
	u32 i, nb_pssh;
	GF_PropertyValue _the_prop;

	//set pssh
	const GF_PropertyValue *p=NULL;

	//only inject if pssh in packet
	if (dyn_pssh_mode==2) {
		GF_FilterPacket *pck;
